  const previous = root.MontazhnayaContextualHelpTranslations || Object.create(null);
  const merged = Object.assign(Object.create(null), previous);
  for (const [locale, translations] of Object.entries(localeTranslations)) {
    const messages = Object.assign(Object.create(null), previous[locale] || {});
    let covered = 0;
    for (const [source, english] of Object.entries(sourceEnglish)) {
      if (Object.prototype.hasOwnProperty.call(translations, english)) {
        messages[source] = translations[english];
        covered++;
      }
    }
    if (covered !== Object.keys(sourceEnglish).length) {
      throw new Error("Contextual-help translation coverage mismatch for " + locale + ": " + covered + "/" + Object.keys(sourceEnglish).length);
    }
    merged[locale] = Object.freeze(messages);
  }
  root.MontazhnayaContextualHelpTranslations = Object.freeze(merged);
  root.MontazhnayaContextualHelpTranslationStatus = Object.freeze({
    locales: Object.freeze(Object.keys(localeTranslations)),
    sourceCount: Object.keys(sourceEnglish).length,
    status: "machine-assisted-draft-native-speaker-review-pending",
    wave: "contextual-live-help-wave-1"
  });
